198	    TORCH_CHECK(tokens.is_cuda() && tokens.scalar_type() == torch::kInt32 && tokens.is_contiguous());
199	    TORCH_CHECK(targets.is_cuda() && targets.scalar_type() == torch::kInt32 && targets.is_contiguous());
200	    const int B = (int)targets.numel();
201	    TORCH_CHECK(tokens.numel() == (int64_t)B * dec::kSeq, "tokens must be [B,kSeq]");
202	    const int64_t total = kDecTotalElems;
203	    TORCH_CHECK(state.is_cuda() && state.scalar_type() == torch::kFloat32 && state.is_contiguous()
204	                && state.numel() >= 3 * total, "state must be contiguous fp32 [>=3*total]");
205	
206	    int dev = params.get_device();
207	    int n_sms = 1;
208	    cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
209	
210	    // Separate cached scalar scratch (DO NOT reuse the TC workspace — different
211	    // layout/size; the TC one under-allocates the scalar nCTA*total partials).
212	    static torch::Tensor s_gn, s_ga, s_gg, s_ws;
213	    static int64_t s_ws_floats = 0;
214	    const int64_t need = (int64_t)n_sms * total + n_sms + 1;
215	    if (!s_gn.defined()) {
216	        auto oi = torch::dtype(torch::kInt32).device(params.device());
217	        s_gn = torch::zeros({1}, oi); s_ga = torch::zeros({1}, oi); s_gg = torch::zeros({1}, oi);
218	    }
219	    if (s_ws_floats < need) {
220	        s_ws = torch::empty({need}, torch::dtype(torch::kFloat32).device(params.device()));
221	        s_ws_floats = need;
222	    }
223	    auto grad = torch::zeros({total}, torch::dtype(torch::kFloat32).device(params.device()));
224	    float* loss_out = s_ws.data_ptr<float>() + (int64_t)n_sms * total + n_sms;
225	
226	    PersistentContext ctx{
227	        s_gn.data_ptr<int>(),
228	        reinterpret_cast<unsigned*>(s_ga.data_ptr<int>()),
229	        reinterpret_cast<unsigned*>(s_gg.data_ptr<int>()),
230	        ::sg::fused::sm90::kDecNumTensors, 0u};
